 if(/\b(eat|eating|eaten|food|diet|dietary)\b/i.test(message)&&/\b(skunk|skunks|pork|pig|pigs|swine|bacon|ham|rabbit|rabbits|hare|hares)\b/i.test(message))return 'eat unclean';
